DATA = {
    "products": ["chair", "dresser"],
    "resources": ["stain", "oak"],
    "profit": {"chair": 43, "dresser": 52},
    "availability": {"stain": 17, "oak": 11},
    "usage": {
        ("chair", "stain"): 1.4,
        ("chair", "oak"): 2,
        ("dresser", "stain"): 1.1,
        ("dresser", "oak"): 3,
    },
}


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.P = pyo.Set(initialize=d["products"])
    model.R = pyo.Set(initialize=d["resources"])

    model.production = pyo.Var(model.P, within=pyo.NonNegativeIntegers)

    def profit_rule(m):
        return sum(d["profit"][p] * m.production[p] for p in m.P)

    model.obj = pyo.Objective(rule=profit_rule, sense=pyo.maximize)

    def resource_rule(m, r):
        return sum(d["usage"][(p, r)] * m.production[p] for p in m.P) <= d["availability"][r]

    model.resource_limit = pyo.Constraint(model.R, rule=resource_rule)

    return model

